// Original official RT UI; generated by prepare_activity_rt_ui.py.
namespace Zjcs.Official.ActivityBattleUI
{
using System;
using Zjcs.Official.ProfessionUI;
using UnityEngine.Rendering;
using UnityEngine.UI;

public class SpineRTUIManager : ISpineRTUIManager, IDisposable
{
	private int mInstanceId;

	private ISpineRTUI mSpineRTUI;

	public SafeAction OnFreeRenderSeat { get; } = new SafeAction();

	public bool RentRenderSeat(int instanceId, ISpineRTUI spineRTUI)
	{
		if (mInstanceId != 0)
		{
			return mInstanceId == instanceId;
		}
		mInstanceId = instanceId;
		mSpineRTUI = spineRTUI;
		return true;
	}

	public void ReturnRenderSeat(int instanceId)
	{
		if (mInstanceId == instanceId)
		{
			mInstanceId = 0;
			mSpineRTUI = null;
			OnFreeRenderSeat?.Invoke();
		}
	}

	public bool TrySetRT(int targetKey, RawImage rawImage)
	{
		if (mSpineRTUI == null || targetKey != mSpineRTUI.TargetKey)
		{
			return false;
		}
		rawImage.texture = (UnityEngine.Texture)mSpineRTUI.RTColorTextureHandle;
		return true;
	}

	public void Dispose()
	{
		mInstanceId = 0;
		mSpineRTUI = null;
		OnFreeRenderSeat.ClearListener();
	}
}
}
